<template>
  <div class="layout-px-spacing">
    <ul class="navbar-nav flex-row mt-2">
      <li>
        <div class="page-header">
          <nav class="breadcrumb-one" aria-label="breadcrumb">
            <ol class="breadcrumb">
              <li class="breadcrumb-item">
                <a href="javascript:;">Unpaid</a>
              </li>
              <li class="breadcrumb-item active" aria-current="page">
                {{ activeGroupId === "4" ? "Vouchers" : "LPOs" }}
              </li>
            </ol>
          </nav>
        </div>
      </li>
    </ul>

    <global-search-field v-model:filterValue="filter" />

    <div class="d-flex align-items-center my-4">
      <!-- Left: tabs -->
      <ul class="nav nav-tabs border-0 flex-shrink-0 me-auto">
        <li class="nav-item">
          <a
            class="nav-link"
            :class="{ active: activeGroupId === '1' }"
            href="javascript:;"
            @click="activeGroupId = '1'"
            >LPO's</a
          >
        </li>
        <li class="nav-item">
          <a
            class="nav-link"
            :class="{ active: activeGroupId === '4' }"
            href="javascript:;"
            @click="activeGroupId = '4'"
            >Vouchers</a
          >
        </li>
      </ul>

      <!-- Center: heading -->
      <h3
        class="text-center m-0 position-absolute start-50 translate-middle-x"
        v-if="!mobileView"
      >
        {{ date.toUpperCase() }}
        {{
          approvalGroup?.group?.toLowerCase().includes("labour")
            ? "LABOUR REQUEST"
            : approvalGroup?.group?.toLowerCase().includes("voucher")
            ? "PAYMENT VOUCHERS"
            : "LOCAL PURCHASE ORDERS"
        }}
      </h3>

      <!-- Right: actions -->
      <div class="d-flex gap-2 ms-auto flex-shrink-0">
        <button class="btn btn-success" @click="printReport()">
          <svg
            xmlns="http://www.w3.org/2000/svg"
            width="26"
            height="26"
            fill="currentColor"
            class="bi bi-printer"
            viewBox="0 0 16 16"
          >
            <path d="M2.5 8a.5.5 0 1 0 0-1 .5.5 0 0 0 0 1" />
            <path
              d="M5 1a2 2 0 0 0-2 2v2H2a2 2 0 0 0-2 2v3a2 2 0 0 0 2 2h1v1a2 2 0 0 0 2 2h6a2 2 0 0 0 2-2v-1h1a2 2 0 0 0 2-2V7a2 2 0 0 0-2-2h-1V3a2 2 0 0 0-2-2zM4 3a1 1 0 0 1 1-1h6a1 1 0 0 1 1 1v2H4zm1 5a2 2 0 0 0-2 2v1H2a1 1 0 0 1-1-1V7a1 1 0 0 1 1-1h12a1 1 0 0 1 1 1v3a1 1 0 0 1-1 1h-1v-1a2 2 0 0 0-2-2zm7 2v3a1 1 0 0 1-1 1H5a1 1 0 0 1-1-1v-3a1 1 0 0 1 1-1h6a1 1 0 0 1 1 1"
            />
          </svg>
        </button>
        <button class="btn btn-primary" @click="getApprovalItems()">Refresh</button>
      </div>
    </div>

    <div class="row layout-top-spacing">
      <div v-if="loading" v-html="tableShimmer()"></div>
      <div v-else class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
        <div class="panel p-0">
          <div class="custom-table table3">
            <v-client-table
              :data="filteredData"
              :columns="columns"
              :options="table_option"
            >
              <template #status="props">
                <span class="badge inv-status" :class="'badge-' + props.row.status.color">
                  {{ props.row.status.name }}
                </span>
              </template>
              <template #requisition="props">
                <router-link
                  v-if="props.row.type === 'Labour Request'"
                  class="text-primary"
                  :to="`/approval/${props.row.requisition}`"
                  title="Click to see requisition"
                  >{{ props.row.requisition }}</router-link
                >
                <router-link
                  v-else
                  class="text-primary"
                  :to="`/requisition/${props.row.requisition}`"
                  title="Click to see requisition"
                  >{{ props.row.requisition }}</router-link
                >
              </template>
              <template #actions="props">
                <a
                  @click="getApprovalChain(props.row)"
                  data-bs-toggle="modal"
                  data-bs-target="#approval"
                  href="javascript:void(0);"
                  class="text-primary me-2"
                >
                  <i class="bi bi-eye text-primary fs-4"></i>
                </a>

                <a
                  v-if="
                    user_permissions.includes('can_print_lpo') &&
                    (props.row?.status?.name === 'approved' ||
                      props.row?.status?.name === 'paid' ||
                      user_permissions.includes('is_programmer'))
                  "
                  href="javascript:void(0);"
                  @click="printGeneralOrder(props.row, props.row.vendor_data)"
                  class="me-2"
                >
                  <i class="bi bi-printer text-success fs-4"></i>
                </a>

                <a
                  v-if="
                    user_permissions.includes('can_print_lpo') &&
                    (props.row?.status?.name === 'approved' ||
                      props.row?.status?.name === 'paid' ||
                      user_permissions.includes('is_programmer'))
                  "
                  href="javascript:void(0);"
                  @click="downloadVoucherPDF(props.row, props.row.vendor_data)"
                  class="text-dark"
                >
                  <i class="bi bi-download fs-4"></i>
                </a>

                <a
                  v-if="user_permissions.includes('can_delete_lpo')"
                  href="javascript:void(0);"
                  @click="deleteApproval(props.row)"
                  class="text-danger"
                >
                  <i class="bi bi-trash fs-4"></i>
                </a>

                <a
                  href="javascript:void(0);"
                  class="text-dark position-relative ms-2"
                  @click="
                    getApprovalChain(props.row);
                    getLogs();
                  "
                  data-bs-target="#note-modal"
                  data-bs-toggle="modal"
                >
                  <i class="bi bi-journal-bookmark-fill text-primary fs-4"></i>
                  <span
                    v-if="props.row.approval_logs > 0"
                    class="position-absolute top-0 start-100 translate-middle badge rounded-pill bg-danger"
                    style="font-size: 9px; min-width: 16px; padding: 2px 4px"
                  >
                    {{ props.row.approval_logs }}
                  </span>
                </a>

                <!-- modal trigger only -->
              </template>
            </v-client-table>
          </div>
        </div>
      </div>
    </div>
  </div>

  <!-- Modal -->
  <div
    class="modal fade mymodal"
    id="approval"
    tabindex="-1"
    role="dialog"
    aria-labelledby="exampleModalLabel"
    aria-hidden="true"
    data-bs-backdrop="false"
    ref="approvalModal"
  >
    <div class="modal-dialog modal-fullscreen" role="document">
      <div class="modal-content">
        <div class="modal-header">
          <h5 class="modal-title" id="exampleModalLabel">Approval Chain</h5>
          <button
            type="button"
            data-dismiss="modal"
            data-bs-dismiss="modal"
            aria-label="Close"
            class="btn-close"
            @click="clearForm()"
            id="close-approval-modal"
          ></button>
        </div>

        <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
          <div class="panel p-0">
            <div class="custom-table table3 table-responsive">
              <table class="table table-bordered table-striped">
                <thead>
                  <tr>
                    <th>Order No</th>
                    <th>Requester</th>
                    <th>Date Requested</th>
                    <th>Purpose</th>
                    <th>Approval Chain</th>
                    <th v-if="item.project">Project</th>
                    <th v-if="item.vendor">
                      <span v-if="item?.type?.toLowerCase().includes('voucher')">
                        Beneficiary
                      </span>
                      <span v-else> Vendor </span>
                    </th>
                    <th>Awaits</th>
                    <th>Cost</th>
                    <th v-if="user_permissions.includes('can_print_lpo')">Action</th>
                    <th>Note</th>
                    <th>Delete</th>
                  </tr>
                </thead>
                <tbody>
                  <tr>
                    <td>{{ item?.order }}</td>
                    <td>{{ item.requester }}</td>
                    <td>{{ item?.date }}</td>
                    <td>{{ item?.type }}</td>
                    <td>{{ item?.purpose }}</td>
                    <td v-if="item.project">{{ item.project }}</td>
                    <td v-if="item.vendor">{{ item.vendor }}</td>
                    <td>{{ item?.awaits }}</td>
                    <td>{{ item?.cost }}</td>
                    <td v-if="user_permissions.includes('can_print_lpo')">
                      <a
                        v-if="
                          user_permissions.includes('can_print_lpo') &&
                          (item?.status?.name === 'approved' ||
                            item?.status?.name === 'paid' ||
                            user_permissions.includes('is_programmer'))
                        "
                        href="javascript:void(0);"
                        @click="printGeneralOrder(item, item.vendor_data)"
                        class="text-success me-2"
                      >
                        <svg
                          xmlns="http://www.w3.org/2000/svg"
                          width="24"
                          height="24"
                          fill="currentColor"
                          class="bi bi-printer"
                          viewBox="0 0 16 16"
                        >
                          <path d="M2.5 8a.5.5 0 1 0 0-1 .5.5 0 0 0 0 1z" />
                          <path
                            d="M5 1a2 2 0 0 0-2 2v2H2a2 2 0 0 0-2 2v3a2 2 0 0 0 2 2h1v1a2 2 0 0 0 2 2h6a2 2 0 0 0 2-2v-1h1a2 2 0 0 0 2-2V7a2 2 0 0 0-2-2h-1V3a2 2 0 0 0-2-2H5zM4 3a1 1 0 0 1 1-1h6a1 1 0 0 1 1 1v2H4V3zm1 5a2 2 0 0 0-2 2v1H2a1 1 0 0 1-1-1V7a1 1 0 0 1 1-1h12a1 1 0 0 1 1 1v3a1 1 0 0 1-1 1h-1v-1a2 2 0 0 0-2-2H5zm7 2v3a1 1 0 0 1-1 1H5a1 1 0 0 1-1-1v-3a1 1 0 0 1 1-1h6a1 1 0 0 1 1 1z"
                          />
                        </svg>
                      </a>
                      <button
                        @click="toggleApproval()"
                        v-if="
                          item.purpose === 'Labour Request' &&
                          user_permissions.includes('can_create_labour_voucher')
                        "
                        class="btn btn-outline-primary"
                      >
                        Create Voucher
                      </button>
                      <router-link
                        :to="`/report/labour-payments/${item.id}`"
                        v-if="item.purpose === 'Labour Request'"
                        class="text-primary"
                      >
                        view History
                      </router-link>
                    </td>
                    <td>
                      <span class="position-relative d-inline-block">
                        <svg
                          xmlns="http://www.w3.org/2000/svg"
                          width="24"
                          height="24"
                          fill="currentColor"
                          class="bi bi-journal-bookmark-fill text-primary"
                          viewBox="0 0 16 16"
                          @click.stop="openNoteModal()"
                        >
                          <path
                            fill-rule="evenodd"
                            d="M6 1h6v7a.5.5 0 0 1-.757.429L9 7.083 6.757 8.43A.5.5 0 0 1 6 8z"
                          />
                          <path
                            d="M3 0h10a2 2 0 0 1 2 2v12a2 2 0 0 1-2 2H3a2 2 0 0 1-2-2v-1h1v1a1 1 0 0 0 1 1h10a1 1 0 0 0 1-1V2a1 1 0 0 0-1-1H3a1 1 0 0 0-1 1v1H1V2a2 2 0 0 1 2-2"
                          />
                          <path
                            d="M1 5v-.5a.5.5 0 0 1 1 0V5h.5a.5.5 0 0 1 0 1h-2a.5.5 0 0 1 0-1zm0 3v-.5a.5.5 0 0 1 1 0V8h.5a.5.5 0 0 1 0 1h-2a.5.5 0 0 1 0-1zm0 3v-.5a.5.5 0 0 1 1 0v.5h.5a.5.5 0 0 1 0 1h-2a.5.5 0 0 1 0-1z"
                          />
                        </svg>
                        <span
                          v-if="item.approval_logs > 0"
                          class="position-absolute top-0 start-100 translate-middle badge rounded-pill bg-danger"
                          style="font-size: 9px; min-width: 16px; padding: 2px 4px"
                        >
                          {{ item.approval_logs }}
                        </span>
                      </span>
                    </td>
                    <td>
                      <a
                        v-if="user_permissions.includes('can_delete_lpo')"
                        href="javascript:void(0);"
                        @click="deleteApproval(item)"
                        class="text-danger"
                      >
                        <svg
                          xmlns="http://www.w3.org/2000/svg"
                          width="24"
                          height="24"
                          fill="currentColor"
                          class="bi bi-trash"
                          viewBox="0 0 16 16"
                        >
                          <path
                            d="M5.5 5.5A.5.5 0 0 1 6 6v6a.5.5 0 0 1-1 0V6a.5.5 0 0 1 .5-.5m2.5 0a.5.5 0 0 1 .5.5v6a.5.5 0 0 1-1 0V6a.5.5 0 0 1 .5-.5m3 .5a.5.5 0 0 0-1 0v6a.5.5 0 0 0 1 0z"
                          />
                          <path
                            d="M14.5 3a1 1 0 0 1-1 1H13v9a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V4h-.5a1 1 0 0 1-1-1V2a1 1 0 0 1 1-1H6a1 1 0 0 1 1-1h2a1 1 0 0 1 1 1h3.5a1 1 0 0 1 1 1zM4.118 4 4 4.059V13a1 1 0 0 0 1 1h6a1 1 0 0 0 1-1V4.059L11.882 4zM2.5 3h11V2h-11z"
                          />
                        </svg>
                      </a>
                    </td>
                  </tr>
                  <tr v-if="item.description">
                    <td colspan="8">
                      <b> Brief Description : </b>
                      {{ item.description }}
                      <span v-if="approval_description">
                        ( {{ approval_description }} )</span
                      >
                    </td>
                  </tr>
                  <tr v-if="item.remark">
                    <td colspan="8"><b> Remark : </b> {{ item.remark }}</td>
                  </tr>
                </tbody>
              </table>
            </div>
          </div>
        </div>

        <div
          v-if="
            item.status?.name === 'approved' &&
            user_permissions.includes('can_complete_transaction') &&
            approvalTransactions.reduce((sum, t) => sum + (t.amount_raw || 0), 0) >=
              approvalTotalCost
          "
          class="d-flex justify-content-center mt-2 mb-2"
        >
          <button
            class="btn btn-primary"
            type="button"
            :disabled="loading"
            @click="complete_transaction = !complete_transaction"
          >
            <span v-if="loading" v-html="loadingSpinner()"></span>
            <span v-else>Paid</span>
          </button>
        </div>
        <form v-if="complete_transaction" @submit.prevent="completeTransaction(item.id)">
          <div class="input-group container">
            <input
              type="text"
              class="form-control"
              placeholder="Enter Any remark "
              v-model="remark"
            />
            <button class="btn btn-primary me-2" type="submit" :disabled="loading">
              <span v-if="loading" v-html="loadingSpinner()"></span>
              <span v-else>Save</span>
            </button>
          </div>
        </form>

        <div class="modal-body">
          <div class="text-center mb-2">
            <div class="btn-group mb-2">
              <button
                class="btn btn-secondary me-2"
                @click="changeStatus(item.id, 3)"
                :disabled="spinner"
                v-if="
                  user_permissions.includes('is_programmer') &&
                  item.status?.name === 'paid'
                "
              >
                Mark Approved
              </button>
              <button
                class="btn btn-success"
                @click="fillReceipt = !fillReceipt"
                :disabled="spinner"
                v-if="
                  user_permissions.includes('can_complete_transaction') &&
                  item.status?.name === 'paid'
                "
              >
                Attach Receipt
              </button>
            </div>

            <div
              v-if="fillReceipt"
              class="d-flex justify-content-center align-items-end gap-2"
            >
              <input
                class="form-control w-25"
                type="file"
                @change="handleFileUpload"
                accept="application/pdf"
                required
              />
              <input type="date" v-model="receipt_date" class="form-control w-25" />

              <button class="btn btn-primary" @click="submitReceipt" :disabled="spinner">
                <span v-if="spinner" v-html="loadingSpinner()"></span>
                <span v-else>Submit</span>
              </button>
            </div>
          </div>

          <!-- <div
            class="d-flex justify-content-center mb-2"
            v-if="
              (user_role_id == awaiter.role_id && awaits !== 'no one') ||
              (user_permissions.includes('is_md') && item.status?.name !== 'paid') ||
              (user_role_id == item.last_checker_id && item.status?.name !== 'paid')
            "
          >
            <div class="btn-group">
              <button
                class="btn btn-secondary me-2"
                @click="changeStatus(item.id, 2)"
                :disabled="spinner"
                v-if="
                  (user_permissions.includes('is_md') ||
                    user_permissions.includes('is_programmer')) &&
                  item.status?.name === 'approved'
                "
              >
                Unapprove
              </button>

              <button
                class="btn btn-primary me-2"
                @click="approval_status = 3"
                :disabled="spinner"
              >
                Check
              </button>
              <button
                class="btn btn-danger me-2"
                @click="approval_status = 4"
                :disabled="spinner"
              >
                Reject
              </button>

              <button
                class="btn btn-info me-2"
                @click="approval_status = 14"
                :disabled="spinner"
              >
                Remark
              </button>

              <button
                class="btn btn-warning"
                @click="approval_status = 17"
                :disabled="spinner"
              >
                On Hold
              </button>
            </div>
          </div> -->

          <!-- <p class="text-center">{{ status == 3 ? 'Enter Approval Remark' : status == 4 ? 'Enter Rejection Remark' : 'Enter Remark' }}</p> -->
          <!-- <div v-if="approval_status" class="mb-2 text-center">
            <span
              class="badge rounded-pill"
              :class="{
                'bg-danger': approval_status == 4,
                'bg-success': approval_status == 3,
                'bg-info': approval_status == 14,
                'bg-warning': approval_status == 17,
              }"
              style="font-size: 1rem"
            >
              {{
                approval_status == 3
                  ? "Check / Approve Request"
                  : approval_status == 4
                  ? "Reject Request"
                  : "Fill Remark"
              }}
            </span>
          </div> -->

          <!-- <div class="input-group" v-if="approval_status">
            <input
              type="text"
              class="form-control"
              :placeholder="
                approval_status == 3
                  ? 'Enter Approval Remark'
                  : approval_status == 4
                  ? 'Enter Rejection Remark'
                  : 'Enter Remark'
              "
              v-model="remark"
            />
            <button
              @click="onApproveClick()"
              class="btn btn-primary me-2"
              type="button"
              :disabled="spinner"
            >
              <span v-if="spinner" v-html="loadingSpinner()"></span>
              <span v-else>Save</span>
            </button>
          </div> -->

          <div class="custom-table table3 table-responsive">
            <table class="table">
              <thead>
                <tr>
                  <th
                    v-for="chain in approvalChain"
                    :key="chain.role_id || chain.position || chain.name"
                  >
                    {{ chain.name }} <br />
                  </th>
                </tr>
              </thead>
              <tbody>
                <tr>
                  <td
                    v-for="(role, idx) in approvalChain"
                    :key="role.role_id || role.position || idx"
                    :class="
                      role?.status?.color ? 'text-' + role.status.color : 'text-danger'
                    "
                  >
                    <span> {{ role?.status?.name ?? "Unchecked" }}</span
                    ><br />
                    <span class="text-dark" v-if="role.approved_at"
                      >Checked At :{{ formatDate(role.approved_at) }}
                    </span>
                    <br />
                    <span class="text-dark" v-if="role.remark"
                      >Remark : {{ role.remark }}</span
                    >
                  </td>
                </tr>
              </tbody>
            </table>
          </div>
          <!-- approval items starts -->
          <h4 class="text-center" style="font-size: 1.3rem">APPROVAL ITEMS</h4>
          <div class="d-flex justify-content-center mb-3">
            <input
              v-if="create_approval"
              type="text"
              class="form-control"
              style="max-width: 350px; font-size: 1rem"
              placeholder="Enter Brief Description "
              v-model="description"
            />
          </div>
          <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
            <div class="panel p-0">
              <div class="custom-table table3 table-responsive">
                <table class="table table-bordered table-striped">
                  <thead>
                    <tr>
                      <th>ID</th>
                      <th>Item</th>
                      <th>Decription</th>
                      <th>Quantity</th>
                      <th>Unit</th>
                      <th>Rate</th>
                      <th>Total</th>
                      <th>Receiver</th>
                      <th v-if="create_approval" class="text-center">select</th>
                      <th>Actions</th>
                    </tr>
                  </thead>
                  <tbody>
                    <tr v-for="reqItem in requisitionItems">
                      <td>{{ reqItem.order_item_id }}</td>
                      <td>{{ reqItem.item }}</td>
                      <td>
                        <router-link
                          class="btn btn-outline-primary"
                          :to="`/requisition-budget/${reqItem.requisition_items.item_id}`"
                          v-if="
                            item.requisition_type === 'budget' &&
                            !reqItem.requisition_items.asset_id
                          "
                        >
                          {{ reqItem.description }}
                        </router-link>
                        <span v-else>
                          <span v-if="reqItem.selected">
                            {{ reqItem.description }} (
                            {{ reqItem.request_description }} )
                          </span>
                          <span v-else>
                            {{ reqItem.description }}
                          </span>
                        </span>
                      </td>
                      <td @click="editApprovalItem(reqItem.id)">
                        {{ reqItem.quantity }}
                        <span v-if="reqItem?.requested_sum">
                          <br />
                          Requested : {{ reqItem?.requested_sum }}
                          <br />
                          Balance :{{
                            (reqItem.quantity - reqItem?.requested_sum).toFixed(2)
                          }}
                        </span>

                        <span v-if="reqItem.selected">
                          <br />Requesting : {{ reqItem.requesting_quantity }}
                        </span>
                        <input
                          v-if="edit_item == reqItem.id"
                          type="number"
                          class="form-control"
                          placeholder="Quantity"
                          step="any"
                          v-model="reqItem.quantity"
                        />
                      </td>
                      <td>
                        {{ reqItem.requisition_items.units }}
                      </td>
                      <td @click="editApprovalItem(reqItem.id)">
                        {{ reqItem.rate }}
                        <input
                          v-if="edit_item == reqItem.id"
                          type="number"
                          class="form-control"
                          placeholder="Quantity"
                          step="any"
                          v-model="reqItem.rate_original"
                        />
                      </td>
                      <td>
                        <span>
                          <!-- {{ reqItem.total }}<br> -->
                          {{ formatNumber(reqItem.quantity * reqItem.rate_original)
                          }}<br />
                        </span>
                        <span v-if="reqItem.selected">
                          Requesting :
                          {{
                            formatNumber(
                              reqItem.requesting_quantity * reqItem.rate_original
                            )
                          }}
                        </span>
                      </td>
                      <td>{{ reqItem.receiver ?? reqItem.beneficiary }}</td>
                      <td v-if="create_approval" class="text-center">
                        <svg
                          v-if="reqItem.selected"
                          @click="reqItem.selected = !reqItem.selected"
                          xmlns="http://www.w3.org/2000/svg"
                          width="26"
                          height="26"
                          fill="currentColor"
                          class="bi bi-check2-circle"
                          viewBox="0 0 16 16"
                        >
                          <path
                            d="M2.5 8a5.5 5.5 0 0 1 8.25-4.764.5.5 0 0 0 .5-.866A6.5 6.5 0 1 0 14.5 8a.5.5 0 0 0-1 0 5.5 5.5 0 1 1-11 0"
