                      >
                        <svg
                          xmlns="http://www.w3.org/2000/svg"
                          width="24"
                          height="24"
                          fill="currentColor"
                          class="bi bi-trash"
                          viewBox="0 0 16 16"
                        >
                          <path
                            d="M5.5 5.5A.5.5 0 0 1 6 6v6a.5.5 0 0 1-1 0V6a.5.5 0 0 1 .5-.5m2.5 0a.5.5 0 0 1 .5.5v6a.5.5 0 0 1-1 0V6a.5.5 0 0 1 .5-.5m3 .5a.5.5 0 0 0-1 0v6a.5.5 0 0 0 1 0z"
                          />
                          <path
                            d="M14.5 3a1 1 0 0 1-1 1H13v9a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V4h-.5a1 1 0 0 1-1-1V2a1 1 0 0 1 1-1H6a1 1 0 0 1 1-1h2a1 1 0 0 1 1 1h3.5a1 1 0 0 1 1 1zM4.118 4 4 4.059V13a1 1 0 0 0 1 1h6a1 1 0 0 0 1-1V4.059L11.882 4zM2.5 3h11V2h-11z"
                          />
                        </svg>
                      </a>
                    </template>
                  </v-client-table>
                </div>
              </div>
            </div>
          </div>

          <div v-if="receipts.length > 0" class="row layout-top-spacing">
            <h4 class="text-center">ORDER RECEIPTS</h4>
            <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
              <div class="panel p-0">
                <div class="custom-table table3">
                  <v-client-table
                    :data="receipts"
                    :columns="receipt_columns"
                    :options="table_option"
                  >
                    <template #attachment="props">
                      <a
                        :href="props.row.attachment"
                        target="_blank"
                        class="badge badge-primary text-white"
                        style="cursor: pointer"
                        @click="fillTransaction(props.row)"
                      >
                        Open Attachment
                      </a>
                    </template>
                  </v-client-table>
                </div>
              </div>
            </div>
          </div>
        </div>

        <div class="modal-footer">
          <button
            type="button"
            class="btn btn-primary"
            data-dismiss="modal"
            data-bs-dismiss="modal"
            @click="clearForm()"
          >
            close
          </button>
          <button
            class="btn btn-success"
            v-if="create_approval"
            @click="createApproval()"
            :disabled="loading"
          >
            <span v-if="loading" v-html="loadingSpinner()"></span>
            <span v-else>Submit</span>
          </button>
        </div>
      </div>
    </div>
  </div>
  <!-- modal ends -->

  <!-- payment modal starts -->

  <div
    class="modal fade mymodal"
    id="payment-proof"
    data-bs-backdrop="false"
    data-bs-keyboard="false"
    tabindex="-1"
    aria-labelledby="staticBackdropLabel"
    aria-hidden="true"
  >
    <div class="modal-dialog modal-xl">
      <div class="modal-content">
        <div class="modal-header">
          <h1 class="modal-title fs-5" id="staticBackdropLabel">PROOF OF PAYMENT</h1>
          <button
            type="button"
            class="btn-close"
            data-bs-dismiss="modal"
            aria-label="Close"
            id="close-proof-modal"
            @click="closeProofModal()"
          ></button>
        </div>
        <div class="modal-body">
          <div class="custom-table table3 table-responsive">
            <table class="table table-bordered table-striped">
              <thead>
                <tr>
                  <th>Order No</th>
                  <th>Item No</th>
                  <th>Requester</th>
                  <th>Date Requested</th>
                  <th>Purpose</th>
                  <th>Approval Chain</th>
                  <th v-if="item.project">Project</th>
                  <th>Cost</th>
                </tr>
              </thead>
              <tbody>
                <tr>
                  <td>{{ proof?.order }}</td>
                  <td>{{ proof_item?.id }}</td>
                  <td>{{ proof.requester }}</td>
                  <td>{{ proof?.date }}</td>
                  <td>{{ proof?.type }}</td>
                  <td>{{ proof?.purpose }}</td>
                  <td v-if="proof.project">{{ proof.project }}</td>
                  <td>
                    {{ formatNumber(proof_item?.quantity * proof_item.rate_original) }}
                  </td>
                </tr>
                <tr v-if="proof_item.item">
                  <td colspan="9">Item : {{ proof_item.item }}</td>
                </tr>
                <tr v-if="proof_item.description">
                  <td colspan="9">Description : {{ proof_item.description }}</td>
                </tr>
                <tr v-if="proof.remark">
                  <td colspan="9">Briefing : {{ proof.remark }}</td>
                </tr>
              </tbody>
            </table>
          </div>
          <div class="row layout-top-spacing">
            <div class="col-xl-12 col-lg-12 col-sm-12 layout-spacing">
              <div class="panel p-0">
                <div class="custom-table table3">
                  <div class="row">
                    <div class="col-md-6">
                      <label class="form-label">Reference Number </label>
                      <input
                        class="form-control"
                        type="text"
                        placeholder="Enter Reference Number"
                        v-model="reference_number"
                      />
                    </div>

                    <div class="col-md-6">
                      <label class="form-label">Paid From </label>
                      <multiselect
                        v-model="account"
                        :options="accounts"
                        placeholder="Select Account"
                        label="name"
                        :searchable="true"
                        multple="false"
                        :required="true"
                        :allow-empty="false"
                      />
                    </div>

                    <div class="col-md-3">
                      <label class="form-label">Amount</label>
                      <input
                        class="form-control"
                        type="number"
                        step="any"
                        placeholder="Enter Amount"
                        v-model="amount"
                      />
                    </div>

                    <div class="col-md-4">
                      <label class="form-label">Receiver</label>
                      <input
                        class="form-control"
                        type="text"
                        placeholder="Enter Receiver"
                        v-model="receiver"
                      />
                    </div>

                    <div class="col-md-2">
                      <label class="form-label">Date </label>
                      <input class="form-control" type="date" v-model="proof_date" />
                    </div>

                    <div class="col-md-3">
                      <label class="form-label">Attachment </label>
                      <input
                        class="form-control"
                        type="file"
                        @change="handleFileUpload"
                        accept="application/pdf"
                      />
                    </div>

                    <div class="col-md-12">
                      <label class="form-label">Remark</label>
                      <input
                        class="form-control"
                        type="text"
                        placeholder="Enter Remark"
                        v-model="description"
                      />
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </div>
        </div>
        <div class="modal-footer">
          <button
            type="button"
            class="btn btn-danger me-2"
            data-bs-dismiss="modal"
            @click="closeProofModal()"
          >
            Close
          </button>
          <button type="button" class="btn btn-success" @click="submitProof()">
            Save
          </button>
        </div>
      </div>
    </div>
  </div>
  <!-- payment modal ends -->

  <div
    class="modal fade mymodal"
    id="note-modal"
    data-bs-backdrop="false"
    data-bs-keyboard="false"
    tabindex="-1"
    aria-hidden="true"
  >
    <div class="modal-dialog modal-lg modal-dialog-centered">
      <div
        class="modal-content"
        style="
          border-radius: 20px;
          max-height: 80vh;
          display: flex;
          flex-direction: column;
        "
      >
        <!-- Header -->
        <div
          class="modal-header"
          style="padding: 14px 18px; border-bottom: 0.5px solid #dee2e6"
        >
          <span style="font-size: 15px; font-weight: 500"
            >Notes for Order No. {{ item?.order }}
          </span>
          <button
            type="button"
            v-if="
              user_permissions.includes('can_request_order_cancellation') &&
              item?.status?.name === 'approved'
            "
            class="btn btn-warning ms-auto"
            @click="cancellation_request = !cancellation_request"
            :disabled="sending"
          >
            <span v-if="sending" v-html="loadingSpinner()"></span>
            <span v-else>Request Cancellation</span>
          </button>
          <button
            type="button"
            class="btn-close ms-auto"
            data-bs-dismiss="modal"
          ></button>
        </div>

        <!-- Body / Feed -->
        <div class="modal-body" style="overflow-y: auto; flex: 1; padding: 16px 18px">
          <div v-if="logsLoading" class="text-center py-4">
            <span v-html="waitIndicator()"></span>
          </div>

          <div v-else-if="logs.length === 0" class="text-center text-muted py-5">
            <svg
              xmlns="http://www.w3.org/2000/svg"
              width="36"
              height="36"
              fill="currentColor"
              class="bi bi-chat-square-dots mb-2 d-block mx-auto"
              viewBox="0 0 16 16"
            >
              <path
                d="M14 1a1 1 0 0 1 1 1v8a1 1 0 0 1-1 1h-2.5a2 2 0 0 0-1.6.8L8 14.333 
                     6.1 11.8a2 2 0 0 0-1.6-.8H2a1 1 0 0 1-1-1V2a1 1 0 0 1 1-1z"
              />
            </svg>
            No notes yet for Order No. {{ item?.order }}
          </div>

          <!-- Comment thread -->
          <div v-else class="d-flex flex-column gap-4">
            <div v-for="log in logs" :key="log.id">
              <!-- Parent comment -->
              <div class="d-flex gap-2 align-items-start">
                <div
                  class="avatar-circle flex-shrink-0"
                  :style="{
                    background: avatarBg(log.reporter?.name),
                    color: avatarColor(log.reporter?.name),
                  }"
                >
                  {{ log.reporter?.name?.charAt(0)?.toUpperCase() }}
                </div>
                <div class="flex-grow-1">
                  <div class="d-flex align-items-center gap-2 mb-1 flex-wrap">
                    <strong style="font-size: 15px">{{ log.reporter?.name }}</strong>
                    <small
                      class="text-dark"
                      style="font-size: 12px; text-transform: lowercase"
                      >{{ log.type }}</small
                    >
                    <small class="text-dark">{{ formatDate(log.created_at) }}</small>
                  </div>
                  <!-- view mode -->
                  <div
                    v-if="editingLog !== log.id"
                    class="d-flex align-items-start gap-3"
                  >
                    <p
                      style="
                        font-size: 16px;
                        line-height: 1.5;
                        margin: 0 0 6px;
                        color: #212529;
                      "
                    >
                      {{ log.description }}
                    </p>

                    <svg
                      xmlns="http://www.w3.org/2000/svg"
                      width="13"
                      height="13"
                      fill="currentColor"
                      class="bi bi-pen-fill"
                      viewBox="0 0 16 16"
                      @click="startEdit(log)"
                      v-if="log.reporter?.id === user_id"
                    >
                      <path
                        d="m13.498.795.149-.149a1.207 1.207 0 1 1 1.707 1.708l-.149.148a1.5 1.5 0 0 1-.059 2.059L4.854 14.854a.5.5 0 0 1-.233.131l-4 1a.5.5 0 0 1-.606-.606l1-4a.5.5 0 0 1 .131-.232l9.642-9.642a.5.5 0 0 0-.642.056L6.854 4.854a.5.5 0 1 1-.708-.708L9.44.854A1.5 1.5 0 0 1 11.5.796a1.5 1.5 0 0 1 1.998-.001"
                      />
                    </svg>

                    <i
                      class="bi bi-trash3 text-danger"
                      style="cursor: pointer"
                      v-if="user_permissions.includes('is_programmer')"
                      @click="deleteRemark(log.id)"
                    ></i>
                  </div>

                  <!-- edit mode -->
                  <div v-else class="d-flex gap-2 align-items-center mb-2">
                    <input
                      type="text"
                      class="form-control form-control-sm"
                      style="border-radius: 20px; font-size: 15px"
                      v-model="editText"
                      @keyup.enter="updateLog(log)"
                      @keyup.escape="cancelEdit()"
                    />
                    <button
                      class="btn btn-sm btn-primary px-3"
                      style="border-radius: 20px; font-size: 12px"
                      @click="updateLog(log)"
                      :disabled="submitting"
                    >
                      Save
                    </button>
                    <button
                      class="btn btn-sm btn-link text-muted p-0"
                      @click="cancelEdit()"
                    >
                      Cancel
                    </button>
                  </div>
                  <div class="d-flex align-items-center gap-3">
                    <!-- LEVEL 1 reply toggle — key: log.id (plain number, no prefix needed since it's the root) -->
                    <button
                      class="btn btn-link btn-sm p-0 text-muted"
                      style="font-size: 15px"
                      @click="
                        replyingTo =
                          replyingTo === `log-${log.id}` ? null : `log-${log.id}`
                      "
                    >
                      <svg
                        width="12"
                        height="12"
                        fill="currentColor"
                        class="me-1"
                        viewBox="0 0 16 16"
                      >
                        <path
                          d="M14 1a1 1 0 0 1 1 1v8a1 1 0 0 1-1 1H4.414A2 2 0 0 0 3 
                               11.586l-2 2V2a1 1 0 0 1 1-1z"
                        />
                      </svg>
                      Reply
                    </button>
                    <small v-if="log.replies?.length" class="text-muted">
                      {{ log.replies.length }}
                      {{ log.replies.length === 1 ? "reply" : "replies" }}
                    </small>
                  </div>

                  <!-- Reply input for level 1 -->
                  <div
                    v-if="replyingTo === `log-${log.id}`"
                    class="d-flex gap-2 align-items-center mt-2"
                  >
                    <input
                      type="text"
                      class="form-control form-control-sm"
                      style="border-radius: 20px; font-size: 15px"
                      :placeholder="`Reply to ${log.reporter?.name}...`"
                      v-model="newMessage"
                      @keyup.enter="submitLog(log.id)"
                    />
                    <button
                      class="btn btn-sm btn-primary px-3"
                      style="border-radius: 20px; font-size: 12px"
                      @click="submitLog(log.id)"
                    >
                      Send
                    </button>
                    <button
                      class="btn btn-sm btn-link text-muted btn-danger p-0"
                      @click="
                        replyingTo = null;
                        newMessage = '';
                      "
                    >
                      Cancel
                    </button>
                  </div>

                  <!-- Replies (level 2) -->
                  <div v-if="log.replies?.length" class="mt-3 d-flex flex-column gap-3">
                    <div
                      v-for="reply in log.replies"
                      :key="reply.id"
                      class="d-flex gap-2 align-items-start"
                    >
                      <div
                        class="avatar-circle avatar-sm flex-shrink-0"
                        :style="{
                          background: avatarBg(reply.reporter?.name),
                          color: avatarColor(reply.reporter?.name),
                        }"
                      >
                        {{ reply.reporter?.name?.charAt(0)?.toUpperCase() }}
                      </div>
                      <div class="flex-grow-1">
                        <div class="d-flex align-items-center gap-2 mb-1 flex-wrap">
                          <strong style="font-size: 15px">{{
                            reply.reporter?.name
                          }}</strong>
                          <small
                            class="text-muted"
                            style="font-size: 13px; text-transform: lowercase"
                            >{{ reply.type }}</small
                          >
                          <small class="text-muted" style="font-size: 13px">{{
                            formatDate(reply.created_at)
                          }}</small>
                        </div>

                        <div v-if="reply.type === 'MESSAGE'">
                          <div
                            v-if="editingLog !== reply.id"
                            class="d-flex align-items-start gap-3"
                          >
                            <p
                              style="
                                font-size: 13px;
                                line-height: 1.5;
                                margin: 0 0 6px;
                                color: #212529;
                              "
                            >
                              {{ reply.description }}
                            </p>

                            <svg
                              xmlns="http://www.w3.org/2000/svg"
                              width="13"
                              height="13"
                              fill="currentColor"
                              class="bi bi-pen-fill"
                              viewBox="0 0 16 16"
                              v-if="log.reporter?.id === user_id"
                              @click="startEdit(reply)"
