        id: item.id,
        quantity: item.requesting_quantity,
        description: item.request_description,
        beneficiary: item.receiver,
      })),
  };
  try {
    const response = await axiosInstance.post("approval-lists", payload);
    showMessage("Request Sent");
    const message =
      JSON.parse(localStorage.getItem("user")).name +
      " Created Voucher from Labour Request " +
