};

const logs = ref([]);
const logsLoading = ref(false);
const newMessage = ref("");
const replyingTo = ref(null);

const getLogs = async (source, source_id) => {
  logsLoading.value = true;
  logs.value = [];
  try {
    const response = await axiosInstance.get(
      `logs?source=LPO&source_id=${approval.value.approval_id}`
    );
    logs.value = response.data;
  } catch (error) {
    showError(error.message);
  } finally {
    logsLoading.value = false;
  }
};

const submitting = ref(false);
const submitLog = async (parent_id = null) => {
  submitting.value = true;
  if (!newMessage.value.trim()) return;
  try {
    await axiosInstance.post("logs", {
      parent_id,
      type: "MESSAGE",
      reporter_id: user_id,
      source: "LPO",
      source_id: approval.value.approval_id,
      module: "LPO & VOUCHERS",
      description: newMessage.value.trim(),
      status_id: 1,
    });
    newMessage.value = "";
    replyingTo.value = null;
    getLogs(item.value.type, item.value.id);
  } catch (error) {
    showError(error.message);
    console.log(error);
  } finally {
    submitting.value.false;
  }
};

const currentUserName = computed(() => JSON.parse(localStorage.getItem("user")).name);

const totalLogCount = computed(() =>
  logs.value.reduce(
    (sum, log) =>
      sum +
      1 +
      (log.replies?.length ?? 0) +
      log.replies?.reduce((s, r) => s + (r.replies?.length ?? 0), 0),
    0
  )
);

