const editingLog = ref(null);
const editText = ref("");

const startEdit = (log) => {
  editingLog.value = log.id;
  editText.value = log.description;
};

const cancelEdit = () => {
  editingLog.value = null;
  editText.value = "";
};

const updateLog = async (log) => {
  if (!editText.value.trim()) return;
  submitting.value = true;
  try {
    await axiosInstance.put(`logs/${log.id}`, {
      description: editText.value.trim(),
    });
    showMessage("Note updated");
    editingLog.value = null;
    editText.value = "";
    getLogs();
  } catch (error) {
    showError(error.message);
    console.log(error);
  } finally {
    submitting.value = false;
  }
};
watch(lpoNumber, (newVal) => {
  date.value = "";
  if (newVal !== null && newVal !== undefined && newVal !== "") {
    getApprovalItems();
  }
});

const binCardColumn = ref(["SNo", "date", "ref_no", "remark", "Dr", "Cr", "balance"]);
const bincard = ref([]);
const statementName = ref("");
const statementIssuer = ref("");
const finalBalance = ref("0.00");
const totalReceived = ref("0.00");
const totalIssued = ref("0.00");

const getStatement = async (id) => {
  loading.value = true;

  try {
    const response = await axiosInstance.get(
      `bin-cards?no_store_item=1&bincard_id=${id}`
    );
    const data = response.data[0];
    statementName.value = data.name || "";
    statementIssuer.value = data.issuer?.name || "N/A";

    let runningBalance = 0;
    let totalReceivedAmount = 0;
    let totalIssuedAmount = 0;

    bincard.value = data.items.map((item, index) => {
      const received = parseFloat(item.received) || 0;
      const issued = parseFloat(item.issued) || 0;

      totalReceivedAmount += received;
      totalIssuedAmount += issued;
      runningBalance += received - issued;

      return {
        id: item.id,
        SNo: index + 1,
        date: formatDate(item.date),
        ref_no: item.ref_no || "--",
        Dr: received ? formatNumber(received) + " " + (data.unit || "") : "--",
        Cr: issued ? formatNumber(issued) + " " + (data.unit || "") : "--",
        balance: formatNumber(runningBalance) + " " + (data.unit || ""),
        remark: item.remark || "--",
        authorized_by: item.issuer?.name || "N/A",
      };
    });

    finalBalance.value = formatNumber(runningBalance) + " " + (data.unit || "");

    totalReceived.value = formatNumber(totalReceivedAmount) + " " + (data.unit || "");

    totalIssued.value = formatNumber(totalIssuedAmount) + " " + (data.unit || "");
  } catch (error) {
    console.log(error);
    showError(error.message);
  } finally {
    loading.value = false;
  }
};

